          text: '前60年、ポンペイウスは東方での処置の承認と兵士への土地分配を、クラッススは徴税請負人の利益を元老院に拒まれていた。カエサルは二人を結びつけ、自らは翌年の執政官をめざした。3人は互いの利益を実現するために協力を約束した。',
