          talk: '約束どおり執政官になったカエサルは、二人の望む法を次々と通しました。さらに、自分の娘ユリアをポンペイウスと結婚させ、同盟をかためます。そしてカエサルは、ガリア、今のフランスのあたりに総督として出かけました。8年にわたる戦いでガリアを征服し、その様子を自ら『ガリア戦記』に書いています。この遠征でカエサルは、莫大な富と、自分にだけ忠実な軍隊を手に入れました。いちばん若い同盟者が、いちばんの実力者になっていったのです。',
