      summary: 'マワーリーは、イスラーム教に改宗した非アラブ人である。ウマイヤ朝ではアラブ人に比べて差別され、改宗してもジズヤ（人頭税）を課されることがあった。その不満がアッバース朝の成立を助け、ムスリムの平等が実現していった。',
