          talk: 'やがて、ペルシア人をはじめ多くの人がイスラーム教に改宗しました。彼らはアラブ人の部族に「保護される」形で仲間に加わったので、マワーリーとよばれます。ところが、改宗すればジズヤを払わなくてよいはずなのに、税収が減るのを嫌った役人に、そのまま取られることがありました。戦いに出ても、アラブ人より給料が少ない。同じ神を信じているのに、なぜ。マワーリーの心には、不満がたまっていきました。',
