          talk: 'ウマイヤ朝の中にも、この不公平を正そうとしたカリフがいました。717年に即位したウマル2世です。彼は、イスラーム教に改宗した人からはジズヤを取らないよう命じたと伝えられています。けれども税が減れば国の財政は苦しくなります。しかもウマル2世は、わずか3年足らずで亡くなってしまいました。不満の火は、消えることなく残ったのです。',
