          talk: 'この不満に目をつけたのが、預言者ムハンマドの叔父の子孫、アッバース家でした。彼らは、イランの東のはずれホラーサーン地方で、マワーリーやシーア派の人々を味方につけます。黒い旗をかかげた軍は西へ進み、750年、ついにウマイヤ朝を倒しました。アッバース朝の誕生です。差別に苦しんだ人々の力が、一つの王朝をひっくり返したのです。',
