          talk: 'アッバース朝は、税のしくみを改めました。ムスリムなら民族に関係なくジズヤは払わない。アラブ人でも土地をもてばハラージュを払う。これで、アラブ人だけが得をする時代は終わります。新しい都バグダードでは、イラン人の官僚が政治を支え、さまざまな民族の学者が集まりました。歴史家は、ウマイヤ朝を「アラブ帝国」、アッバース朝を「イスラーム帝国」とよんで区別します。その分かれ目にいたのが、マワーリーだったのです。',
