      period: '1791〜1945年', region: 'europe', view: 'world', tags: ['sogo'],
      summary: '女性参政権は、女性が選挙に参加する権利である。1893年にニュージーランドで最初に国政で認められ、第一次世界大戦での女性の貢献を背景にイギリス・アメリカ・ドイツなどでも実現した。日本では1945年に認められた。',
