          text: '日本では市川房枝らが女性参政権を求めて運動したが、戦前には実現しなかった。1945年12月、敗戦後の改革で衆議院議員選挙法が改正され、女性参政権が認められた。翌1946年4月の総選挙で女性が初めて投票し、39人の女性議員が誕生した。',
          talk: '日本でも、大正時代から平塚らいてうや市川房枝らが女性の参政権を求めてきましたが、戦前には実現しませんでした。扉が開いたのは、敗戦直後の1945年12月です。翌1946年4月の総選挙では、多くの女性が初めて投票所に足を運び、39人の女性議員が誕生しました。ちなみにスイスで国政の女性参政権が認められたのは1971年。今では当たり前の一票も、国によっては、ほんの数十年前に勝ちとられたものなのです。',
          place: '東京', lon: 139.75, lat: 35.68, span: 8,
          polities: ['japan']
