      period: '前594〜前322年', region: 'europe', view: 'aegean', tags: ['tankyu', 'sogo'],
      summary: '直接民主政は、市民が代表者を通さず直接政治に参加する民主政治である。古代アテネでは成年男性市民が民会に出席して国の大事を決めた。ただし女性・奴隷・在留外人は参加できなかった。',
