          talk: 'アテネの民主政は、ある日突然生まれたのではありません。前594年、ソロンは借金のかたに市民が奴隷にされるのを禁じました。前508年ごろにはクレイステネスが、昔からの血のつながりで分かれていた4つの部族を、住んでいる場所による10の部族に組みかえます。有力な家どうしの争いを弱めるためです。また、独裁者になりそうな人の名前を陶器のかけらに書いて投票し、10年間追放する陶片追放の制度もつくられたといわれます。',
