          text: 'ペルシア戦争後、三段櫂船のこぎ手として活躍した無産市民の発言力が高まり、ペリクレスの時代に民主政は完成した。成年男性市民はだれでもプニュクスの丘の民会に出て発言・投票でき、役人の多くはくじで選ばれ、日当も支払われた。',
          talk: 'ペルシア戦争でアテネを救ったのは、軍船をこいだ貧しい市民たちでした。命をかけて戦った以上、政治にも口を出す権利がある。こうして前5世紀半ば、ペリクレスの時代に民主政は完成します。18歳以上の男性市民なら、だれでもプニュクスの丘で開かれる民会に出て、発言し、手をあげて投票できました。多くの役人はくじ引きで選ばれ、仕事を休んで参加する人には日当が払われました。貧しい人も政治に参加できるくふうです。',
