          talk: '荘園で働く農民の多くは、農奴とよばれる人々でした。農奴は、1週間のうち何日かは領主の畑で働き、残りの日に自分の畑を耕します。収穫の一部は領主に納め、結婚するときや、親が亡くなって土地を引き継ぐときにも税を払いました。村を勝手に出ていくこともできません。ただし、売り買いされる奴隷とはちがい、家族をもち、自分の家や道具をもつことは認められていました。さらに教会には、収穫の10分の1を納める十分の一税もありました。',
