          talk: 'ところが、制度は思わぬ方向へ進みます。中正官になったのは、結局その土地の有力な家の人々でした。彼らは自分たちの仲間の子どもに、よい評価をつけます。西晋の時代には、「上品に寒門なく、下品に勢族なし」といわれました。高い評価の人に貧しい家の出身者はおらず、低い評価の人に有力な家の出身者はいない、という意味です。才能を選ぶはずの制度が、生まれた家で人生が決まる制度になってしまったのです。',
