          talk: 'お経の意味が、訳によってばらばらだ。本当のことを知るには、インドに行って元の経典を読むしかない。若い僧、玄奘はそう決心しました。ところが、唐はまだ建国まもなく、国の外へ出ることを禁じていました。629年、玄奘は許可のないまま長安をたちます。関所の役人の目をのがれ、たったひとりで砂漠を越えたとき、水の袋を落としてしまい、5日間水を飲めずに倒れかけたと伝えられています。',
