          talk: 'お金を払えば、罪が許され、天国に近づける。16世紀の初め、ドイツではそんな贖宥状、いわゆる免罪符が売られていました。ローマのサン=ピエトロ大聖堂を建て直す資金集めのためです。1517年、ヴィッテンベルク大学の教授ルターは、これに疑問をもち、95か条の論題を発表しました。人が救われるのは、お金や行いによってではなく、ただ神を信じる心によってだ。この主張は、活版印刷で刷られ、あっという間にドイツ中に広まりました。',
