          text: '巨大な建設事業は帝国の財政を圧迫した。1658年、シャー=ジャハーンは息子アウラングゼーブに帝位を奪われ、アグラ城に幽閉された。晩年の皇帝は城の窓からタージ=マハルをながめて暮らしたと伝えられ、死後は妃の隣に葬られた。',
          talk: '美しい建物には大きな代償もありました。タージ=マハルをはじめ、シャー=ジャハーンの数々の建築は、帝国の財政を苦しめたのです。1657年、皇帝が病気になると、息子たちのあいだで後継ぎ争いがおこり、勝ったアウラングゼーブは父をアグラ城に閉じこめてしまいました。それから8年、年老いた皇帝は、城の窓からヤムナー川の向こうのタージ=マハルをながめて暮らしたと伝えられています。死後、彼は愛する妃の隣に葬られました。',
          place: 'アグラ城', lon: 78.02, lat: 27.18, span: 0.4,
