          talk: 'タージ=マハルは1983年、世界遺産に登録されました。今では年間数百万人が訪れるインドを代表する観光地です。ところが近年、白い大理石が黄色っぽく変色するという問題がおきています。原因は、周辺の工場や車から出る大気汚染です。インド政府は、近くの工場を規制し、車の乗り入れを制限するなどの対策をとっています。370年前に一人の皇帝が愛のために建てた建物を、どう未来に残すか。私たちに投げかけられた問いでもあります。',
          place: 'アグラ', lon: 78.04, lat: 27.17, span: 1,
