          talk: 'イギリスでは17世紀、王と議会が激しく争いました。内乱で王が処刑されたこともあります。1688年、議会はカトリックを復活させようとしたジェームズ2世を追い出し、オランダからウィリアム3世と妻のメアリ2世を王に迎えました。血を流さずに行われたので名誉革命とよばれます。翌年の権利の章典で、王は議会の同意がなければ税をとることも、軍隊を置くこともできなくなりました。国を動かす中心が、王から議会へと移ったのです。',
