          talk: 'その役を果たしたのが、ホイッグ党のロバート=ウォルポールでした。1721年、南海会社という貿易会社の株が暴落し、多くの人が財産を失う南海泡沫事件がおこります。その混乱をおさめたウォルポールは、第一大蔵卿として閣議をとりしきるようになりました。彼が実質的にイギリス最初の首相とされます。ウォルポールは戦争を避けて国の借金を減らし、約20年も政権を担いました。首相官邸として知られるダウニング街10番地の家も、国王から彼に与えられたものです。',
          place: 'ダウニング街10番地', lon: -0.128, lat: 51.503, span: 0.3,
