          talk: '1742年、ウォルポールはスペインとの戦争をめぐって批判を受け、下院で支持を失いました。このとき国王ジョージ2世は、まだ彼を信頼していました。それでもウォルポールは辞職したのです。ここが大事な点です。内閣が続けられるかどうかを決めるのは、王の気持ちではなく、議会の多数の支持だ、という前例ができたのです。こうして、内閣が議会に責任を負う責任内閣制が生まれ、「国王は君臨すれども統治せず」という言葉がイギリス政治の原則となっていきました。',
