          talk: 'この制度は、19世紀のイギリスで、保守党と自由党の二大政党が交代で政権を担う形とともに発展しました。そして、世界の多くの国の議会政治のお手本になります。日本では1885年に内閣制度がつくられ、伊藤博文が初代の総理大臣となりました。ただし戦前の内閣は天皇に責任を負う形でした。戦後の日本国憲法では、内閣は国会に責任を負うと定められています。衆議院で内閣不信任案が可決されると、内閣は総辞職するか、衆議院を解散しなければなりません。そのルーツは、ウォルポールの辞職にあるのです。',
