          text: 'ルソー（1712〜78年）はスイスのジュネーヴに時計職人の子として生まれ、正規の教育をほとんど受けずに各地を放浪した。1755年の『人間不平等起源論』では、私有財産の成立が人間の不平等を生んだと論じ、文明社会を批判した。',
          talk: 'ルソーは、ジュネーヴの時計職人の家に生まれました。母は生まれてまもなく亡くなり、16歳で町を飛び出して放浪生活に入ります。学校にはほとんど通っていません。それでも彼は、パリに出て思想家として名をあげました。1755年の『人間不平等起源論』で、ルソーは問いかけます。人間はもともと自由で平等だったのに、なぜこれほど不平等になったのか。答えは、だれかが土地を囲いこみ、「これはわたしのものだ」と言いだしたときに始まった、というのです。',
