          talk: 'ルソーは1778年、フランス革命を見ることなく亡くなりました。けれども、彼の本は革命家たちの必読書となります。1789年の人権宣言は「あらゆる主権の源は本質的に国民にある」とうたいました。とりわけルソーを崇拝したのが、ジャコバン派のロベスピエールです。1793年の憲法では男性の普通選挙が定められました。一方で、一般意志の名のもとに反対派を次々と処刑する恐怖政治もおこなわれます。ルソーの思想が、人を解放もし、しばりもしたのです。',
          place: 'パリ', lon: 2.35, lat: 48.86, span: 1,
          people: ['rousseau', 'robespierre'], polities: ['france-rev']
