          talk: 'ルソーの思想は、遠く日本にも届きました。明治時代、フランスに留学した中江兆民は、『社会契約論』の一部を漢文に訳し、1882年に『民約訳解』として出版します。兆民は「東洋のルソー」とよばれ、国会の開設や憲法を求める自由民権運動の人々に大きな影響を与えました。一方フランスでは、革命政府がルソーをたたえ、1794年、その遺骸をパリのパンテオンに移しています。生きているあいだ追われる身だった思想家は、死後、国の英雄になったのです。',
          place: '東京', lon: 139.75, lat: 35.68, span: 10,
          polities: ['japan-empire']
