          talk: '憲法の中身を見てみましょう。主権は天皇にあり、軍を指揮する統帥権や、議会を開いたり解散したりする権限など、大きな力が天皇に与えられました。国民は「臣民」とよばれ、言論や信教の自由などは、法律の範囲内で認められました。一方で、法律や予算には議会の同意が必要となります。1890年、初めての衆議院選挙が行われました。ただし、選挙権をもてたのは、一定額以上の税を納める25歳以上の男性だけ。人口の約1%にすぎませんでした。',
