          talk: '1937年7月、北京の郊外の盧溝橋で日中両軍が衝突し、日中戦争が始まりました。日本の軍や政府は、短い期間で勝てると考えていました。ところが、首都の南京を占領しても、蔣介石の国民政府は奥地へ移って戦い続けます。戦争は終わりが見えなくなりました。第一次世界大戦で、ヨーロッパの国々は兵士だけでなく、工場も食料も国民の暮らしもすべてつぎこむ総力戦を経験していました。日本も、その準備をしなければならないと考えたのです。',
